import math

def is_perfect_cube(n):
    if n == 0:
        return True

    # Handle negative numbers
    sign = 1 if n > 0 else -1
    abs_n = abs(n)

    # Calculate the cube root of the absolute value
    # Using round() after cbrt is generally good for checking integer cubes
    root = round(abs_n**(1/3))

    # Check if the cube of the rounded root equals the absolute value
    return root**3 == abs_n

def E(x):
    return (8 * x - 41) * (x + 3)**2

# Range 1: [-10, 10]
range1 = range(-10, 11)
results1 = {}
for x in range1:
    value = E(x)
    is_cube = is_perfect_cube(value)
    results1[x] = (value, is_cube)

print("--- Range [-10, 10] Results ---")
