import math

def check_solution_d5(p):
    # We are solving v^3 - 8p^3 = -13, or v^3 = 8*p^3 - 13
    if p % 5 == 1:
        return "Excluded by constraint p != 1 (mod 5)"

    target_v_cubed = 8 * (p**3) - 13

    # Check if target_v_cubed is a perfect cube
    if target_v_cubed < 0:
        # Find cube root of negative number
        root = -round((-target_v_cubed)**(1/3))
    else:
        root = round(target_v_cubed**(1/3))

    # Verification
    if root**3 == target_v_cubed:
        return f"Solution found for p={p}: v={root}"
    else:
        return f"No integer solution for p={p}: v^3 = {target_v_cubed}"

# Check small values of p, excluding p = 1, 6, 11, ...
P_values = [0, 2, 3, 4, 5, 7, 8, 9, 10, 12] 

